#!/usr/bin/env python3
"""Create an audiobook from Paul Graham essays."""

import html
import json
import os
import re
import shutil
import subprocess
import sys
import urllib.request
from html.parser import HTMLParser

MONTHS = (
    "January February March April May June July August September October November December"
).split()
MONTH_RE = re.compile(r"^(%s)\s+\d{4}$" % "|".join(MONTHS))


class TextExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self.parts = []
        self._skip = False

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        if tag in {"script", "style"}:
            self._skip = True
            return
        if tag in {"br", "p", "div", "hr", "tr"}:
            self.parts.append("\n")

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag in {"script", "style"}:
            self._skip = False
            return
        if tag in {"p", "div", "tr"}:
            self.parts.append("\n")

    def handle_data(self, data):
        if not self._skip:
            self.parts.append(data)


def fetch_html(url: str) -> str:
    req = urllib.request.Request(
        url, headers={"User-Agent": "Mozilla/5.0 (Codex Audiobook)"}
    )
    with urllib.request.urlopen(req, timeout=30) as resp:
        return resp.read().decode("utf-8", errors="replace")


def html_to_text(html_doc: str) -> str:
    parser = TextExtractor()
    parser.feed(html_doc)
    text = html.unescape("".join(parser.parts))
    return text


def extract_essay_text(title: str, html_doc: str) -> str:
    raw_text = html_to_text(html_doc)
    lines = [line.strip() for line in raw_text.splitlines() if line.strip()]

    # Drop leading title if present.
    if lines and lines[0].lower() == title.lower():
        lines = lines[1:]

    date_line = None
    start_idx = 0
    for i, line in enumerate(lines):
        if MONTH_RE.match(line):
            date_line = line
            start_idx = i
            break

    if date_line is None:
        body_lines = lines
    else:
        body_lines = lines[start_idx + 1 :]

    body = " ".join(body_lines)
    body = re.sub(r"\[[0-9]+\]", "", body)
    body = re.sub(r"\s+", " ", body).strip()

    parts = [f"Essay: {title}."]
    if date_line:
        parts.append(f"Published {date_line}.")
    parts.append(body)
    parts.append("End of essay.")

    return " ".join(parts).strip()


def clean_text_for_tts(text: str) -> str:
    text = re.sub(r"http[s]?://\S+", "", text)
    text = re.sub(r"\s+", " ", text)
    text = re.sub(r"[^\w\s.,!?;:'\"()-]", "", text)
    return text.strip()


def chunk_text(text: str, max_chars: int = 3500):
    sentences = re.split(r"(?<=[.!?])\s+", text)
    chunks = []
    current = ""
    for sentence in sentences:
        if not sentence:
            continue
        if len(current) + len(sentence) + 1 <= max_chars:
            current = f"{current} {sentence}".strip()
        else:
            if current:
                chunks.append(current)
            current = sentence
    if current:
        chunks.append(current)
    return chunks


def post_json(url: str, headers: dict, payload: dict) -> bytes:
    data = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(url, data=data, headers=headers, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=120) as resp:
            return resp.read()
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", errors="replace")
        raise RuntimeError(f"HTTP {exc.code} from {url}: {detail}") from exc


def create_with_elevenlabs(text: str, output_path: str) -> bool:
    api_key = os.environ.get("ELEVENLABS_API_KEY")
    if not api_key:
        return False

    voice_id = "21m00Tcm4TlvDq8ikWAM"  # Rachel
    chunks = chunk_text(text, max_chars=3500)
    audio_files = []

    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/audiobook_chunk_{i:04d}.mp3"
        payload = {
            "text": chunk,
            "model_id": "eleven_turbo_v2_5",
            "voice_settings": {"stability": 0.5, "similarity_boost": 0.75},
        }
        audio = post_json(
            f"https://api.elevenlabs.io/v1/text-to-speech/{voice_id}",
            headers={
                "xi-api-key": api_key,
                "Content-Type": "application/json",
            },
            payload=payload,
        )
        with open(chunk_file, "wb") as f:
            f.write(audio)
        audio_files.append(chunk_file)

    return concatenate_audio(audio_files, output_path)


def create_with_openai(text: str, output_path: str) -> bool:
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        return False

    chunks = chunk_text(text, max_chars=3500)
    audio_files = []

    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/audiobook_chunk_{i:04d}.mp3"
        payload = {
            "model": "tts-1",
            "input": chunk,
            "voice": "onyx",
            "response_format": "mp3",
        }
        audio = post_json(
            "https://api.openai.com/v1/audio/speech",
            headers={
                "Authorization": f"Bearer {api_key}",
                "Content-Type": "application/json",
            },
            payload=payload,
        )
        with open(chunk_file, "wb") as f:
            f.write(audio)
        audio_files.append(chunk_file)

    return concatenate_audio(audio_files, output_path)


def create_with_espeak(text: str, output_path: str) -> bool:
    espeak = shutil.which("espeak") or shutil.which("espeak-ng")
    if not espeak:
        return False

    chunks = chunk_text(text, max_chars=1200)
    audio_files = []
    for i, chunk in enumerate(chunks):
        wav_file = f"/tmp/audiobook_chunk_{i:04d}.wav"
        mp3_file = f"/tmp/audiobook_chunk_{i:04d}.mp3"
        subprocess.run([espeak, "-w", wav_file, chunk], check=True)
        subprocess.run(["ffmpeg", "-y", "-i", wav_file, mp3_file], check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        os.remove(wav_file)
        audio_files.append(mp3_file)

    return concatenate_audio(audio_files, output_path)


def concatenate_audio(audio_files, output_path: str) -> bool:
    if not audio_files:
        return False

    list_file = "/tmp/audio_list.txt"
    with open(list_file, "w") as f:
        for audio_file in audio_files:
            f.write(f"file '{audio_file}'\n")

    result = subprocess.run(
        [
            "ffmpeg",
            "-y",
            "-f",
            "concat",
            "-safe",
            "0",
            "-i",
            list_file,
            "-c",
            "copy",
            output_path,
        ],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
    )

    for audio_file in audio_files:
        try:
            os.remove(audio_file)
        except FileNotFoundError:
            pass
    try:
        os.remove(list_file)
    except FileNotFoundError:
        pass

    return result.returncode == 0


def main():
    essays = [
        {
            "title": "Do Things that Don't Scale",
            "url": "https://paulgraham.com/ds.html",
        },
        {
            "title": "Founder Mode",
            "url": "https://paulgraham.com/foundermode.html",
        },
    ]

    combined_parts = []
    for essay in essays:
        print(f"Fetching: {essay['url']}")
        html_doc = fetch_html(essay["url"])
        essay_text = extract_essay_text(essay["title"], html_doc)
        if len(essay_text) < 1000:
            print(f"WARNING: Extracted text seems short for {essay['title']}")
        combined_parts.append(essay_text)

    combined_text = " ".join(combined_parts)
    combined_text = clean_text_for_tts(combined_text)

    output_path = "/root/audiobook.mp3"

    if os.environ.get("ELEVENLABS_API_KEY"):
        print("Using ElevenLabs TTS")
        success = create_with_elevenlabs(combined_text, output_path)
    elif os.environ.get("OPENAI_API_KEY"):
        print("Using OpenAI TTS")
        success = create_with_openai(combined_text, output_path)
    else:
        print("Using local eSpeak TTS")
        success = create_with_espeak(combined_text, output_path)

    if not success:
        raise RuntimeError("Failed to create audiobook")

    print(f"Audiobook saved to {output_path}")


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        print(f"ERROR: {exc}")
        sys.exit(1)
PY"}
